public partial class MainWindow:Window {
 readonly Repository repo;readonly Backend backend;readonly List<FieldEditor> fieldEditors=new();readonly DispatcherTimer timer=new(){Interval=TimeSpan.FromSeconds(8)};bool busy,closing,allowClose,ready,closeRequested;Point dragStart;ModItem? dragItem;readonly ObservableCollection<RotationEntry> rotationRows=new();Point rotationDragStart;RotationEntry? rotationDrag;bool loadingRotation;
 public MainWindow(){InitializeComponent();FitBf4Window();repo=new Repository(AppContext.BaseDirectory);repo.Load();AutoCleanLogsCheckBox.IsChecked=repo.Config.AutoCleanLogs;backend=new Backend(repo);backend.Output+=s=>Dispatcher.BeginInvoke(()=>Log(s));ConfigureFeedback();SourceServerBox.Text=repo.Config.SourceServer;GameDirectoryBox.Text=repo.Config.GameDirectory;PlayerIdBox.Text=repo.Config.PlayerId;ModsList.ItemsSource=modCards;RefreshModCards();PrepareManagementModel();BuildFields();InstallManagementViews();InstallClientDiagnostics();InstallV2Controls();Resources["RotationMaps"]=repo.Maps;Resources["RotationModes"]=repo.Modes;AddMapCombo.ItemsSource=repo.Maps;AddModeCombo.ItemsSource=repo.Modes;AddModeCombo.SelectionChanged+=(s,e)=>FilterRotationMaps();AddMapCombo.SelectedIndex=0;AddModeCombo.SelectedIndex=0;RotationGrid.ItemsSource=rotationRows;LoadRotationEditor();RefreshLabels();RefreshBf4Navigation("launch");ready=true;timer.Tick+=async(s,e)=>{if(!busy)await RefreshState(false);};if(!App.UiPreview)timer.Start();Loaded+=async(s,e)=>{if(App.UiPreview)return;backend.EnsureExternalMods();Log("BF4 启动器 0.3.0-1107 · v2 已就绪。");await RefreshState(false);};}
 void Log(string text){ObserveProgressLog(UiText.Summary(text));var line=DateTime.Now.ToString("HH:mm:ss")+"  "+text;LogBox.AppendText(line+Environment.NewLine);LogBox.ScrollToEnd();try{Directory.CreateDirectory(Path.Combine(repo.Root,"logs"));File.AppendAllText(Path.Combine(repo.Root,"logs",DateTime.Now.ToString("yyyy-MM-dd")+".log"),line+Environment.NewLine,Encoding.UTF8);}catch{}}
 async Task Work(string title,Func<Task> action,OperationKind kind=OperationKind.General){
  if(busy){StatusText.Text="正在"+activeOperation+"，完成后可继续操作。";return;}
  busy=true;BusyBar.Visibility=Visibility.Visible;BeginOperation(title,kind);StatusText.Text=title;bool success=false;string? error=null;
  try{await action();success=true;}
  catch(Exception ex){error=UiText.Summary(ex.Message);Log(ex.ToString());if(kind is OperationKind.StartServer or OperationKind.RestartServer or OperationKind.StopServer){awaitingServerReady=false;if(backend.Initialized)await RefreshState(false);else PaintReadiness(RuntimeReadiness.Stopped);}}
  finally{busy=false;BusyBar.Visibility=Visibility.Collapsed;FinishOperation(success,error);RefreshLabels();if(closeRequested&&!closing){closeRequested=false;_ = Dispatcher.BeginInvoke(new Action(Close));}}
 }
 void RefreshLabels(){EngineLabel.Text="PowerShell "+repo.Config.PowerShell;PermissionLabel.Text=Backend.IsAdmin?"管理员 · 本机离线 BOT":"普通权限 · 本机离线 BOT";UpdatePrivilegeNotice(Backend.IsAdmin);InitializedLabel.Text=backend.Initialized?"已初始化":"待初始化";InitButton.Content=backend.Initialized?"检查并修复运行环境":"初始化 v2 运行环境";var enabled=repo.Config.Mods.Count(x=>x.Enabled);ModSummary.Text=enabled+" 个模组已启用";ModsCount.Text=repo.ModCards.Count+" 个模组  /  "+repo.Config.Mods.Count(m=>m.HasFiles)+" 个版本  /  "+enabled+" 个已启用";try{var plan=repo.Plan();ModPlanText.Text=plan.Owners.Count+" 项服务端参数由模组覆盖。顺序和开关已保存。";foreach(var ed in fieldEditors)ed.SetOverride(plan.Values.GetValueOrDefault(ed.Field.Id),plan.Owners.GetValueOrDefault(ed.Field.Id));RefreshPresetEditors(plan.Owners.ContainsKey("serverPreset")?plan.Values["serverPreset"]?.ToString():null);}catch(Exception ex){ModPlanText.Text=ex.Message;RefreshPresetEditors();}if(!backend.Initialized){TopStatus.Text="尚未初始化";if(!busy)PaintReadiness(RuntimeReadiness.Stopped);}}
 void SavePaths(){repo.Config.SourceServer=SourceServerBox.Text.Trim().Trim('"');repo.Config.GameDirectory=GameDirectoryBox.Text.Trim().Trim('"');var id=PlayerIdBox.Text.Trim();if(id.Length==0||id.Length>64||id.IndexOfAny(new[]{'\r','\n','='})>=0)throw new Exception("玩家 ID 为 1～64 个字符，不能包含等号或换行。");repo.Config.PlayerId=id;repo.Save();}
 void Navigate_Click(object sender,RoutedEventArgs e){var requested=(sender as Button)?.Tag?.ToString();if(NavigateManagement(requested))return;var tag=requested=="rotation"?"launch":requested;LaunchPage.Visibility=tag=="launch"?Visibility.Visible:Visibility.Collapsed;ModsPage.Visibility=tag=="mods"?Visibility.Visible:Visibility.Collapsed;ServerPage.Visibility=tag=="server"?Visibility.Visible:Visibility.Collapsed;RefreshBf4Navigation(requested??"launch");PageTitle.Text=requested=="rotation"?"地图轮换":tag=="mods"?"模组管理":tag=="server"?"服务端设置":"开服与启动";PageSubtitle.Text=requested=="rotation"?"配置地图、顺序与每项回合数。":tag=="mods"?"选择自己的组合，让加载顺序清楚可见。":tag=="server"?"基础设置与模组覆盖，分别管理。":"自己的配置，一套完整的离线环境。";if(requested=="rotation")Dispatcher.BeginInvoke(new Action(ScrollBf4RotationToTop),DispatcherPriority.Loaded);else if(tag=="launch")LaunchPage.ScrollToTop();}
 void PickFolder_Click(object sender,RoutedEventArgs e){using var dialog=new System.Windows.Forms.FolderBrowserDialog{Description=(sender as Button)?.Tag?.ToString()=="server"?"选择原版 Server 文件夹":"选择 BF4 游戏目录",UseDescriptionForTitle=true};if(dialog.ShowDialog()==System.Windows.Forms.DialogResult.OK){if((sender as Button)?.Tag?.ToString()=="server"){SourceServerBox.Text=dialog.SelectedPath;var parent=Directory.GetParent(dialog.SelectedPath)?.FullName;if(parent!=null&&File.Exists(Path.Combine(parent,"bf4_no_drm.exe")))GameDirectoryBox.Text=parent;}else GameDirectoryBox.Text=dialog.SelectedPath;}}
 void AutoCleanLogs_Click(object sender,RoutedEventArgs e){if(!ready)return;bool previous=repo.Config.AutoCleanLogs;try{repo.SetAutoCleanLogs(AutoCleanLogsCheckBox.IsChecked==true);var enabled=repo.Config.AutoCleanLogs;StatusText.Text=enabled?"自动清理日志已开启":"自动清理日志已关闭";ShowNotice(StatusText.Text,enabled?"下次停服时，先保存进度并停止服务，再清理本实例日志。":"停服后保留运行日志。");}catch(Exception ex){repo.Config.AutoCleanLogs=previous;AutoCleanLogsCheckBox.IsChecked=previous;ShowNotice("设置未保存",ex.Message,true);}}
