 async void Initialize_Click(object sender,RoutedEventArgs e)=>await Work("初始化本地环境",async()=>{SavePaths();await backend.Initialize();Log("初始化完成，配置与运行文件已独立保存。");await RefreshState(false);},OperationKind.Initialize);
 async void Control_Click(object sender,RoutedEventArgs e){var action=(sender as Button)?.Tag?.ToString()??"Start";var kind=action=="Stop"?OperationKind.StopServer:action=="Start"?OperationKind.StartServer:OperationKind.RestartServer;await Work((sender as Button)?.Content?.ToString()??"服务操作",async()=>{SavePaths();await backend.Control(action);await RefreshState(false);if(action=="Stop"&&!string.IsNullOrWhiteSpace(backend.LastLogCleanupMessage))SetCompletion("服务已停止",backend.LastLogCleanupMessage);},kind);}
 async void LaunchGame_Click(object sender,RoutedEventArgs e)=>await Work("启动游戏",async()=>{SavePaths();var result=await backend.Launch();var feedback=ClientLaunchFeedback.From(result);Log(feedback.Detail);SetCompletion(feedback.Title,feedback.Detail,!feedback.Ready);await RefreshState(false);},OperationKind.LaunchGame);
 async void Refresh_Click(object sender,RoutedEventArgs e)=>await Work("刷新运行状态",()=>RefreshState(true));
 async Task RefreshState(bool showError){try{await RefreshManagementAsync(false);var s=await backend.Snapshot();if(s==null){UpdateModuleFeedback(null);return;}var online=s["online"]?.GetValue<bool>()==true;if(online)backend.EnsureExternalMods();BlazeState.Text=s["blaze"]?.GetValue<bool>()==true?"运行中":"未启动";GameState.Text=online?(s["gameState"]?.ToString()=="IN_GAME"?"对局进行中":"准备中"):"未连接";MapLabel.Text=s["map"]?.ToString()??"等待连接";PlayerState.Text=(s["players"]?.ToString()??"—")+" / 64";var readiness=RuntimeStatusLogic.Evaluate(online,s["blaze"]?.GetValue<bool>()==true,s["gameState"]?.ToString(),s["botReady"]?.GetValue<bool>()==true);PaintReadiness(readiness);TopStatus.Text=readiness==RuntimeReadiness.Ready?"服务完全启动":readiness==RuntimeReadiness.Preparing?"服务准备中":"服务未启动";var module=Path.Combine(repo.Root,"data","module-state.json");if(File.Exists(module)){var m=JsonNode.Parse(await File.ReadAllTextAsync(module));var moduleFresh=Math.Abs(DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()-(m?["at"]?.GetValue<long>()??0))<10000;FeatureStatus.Text=moduleFresh?UiText.Summary(m?["summary"]?.ToString(),"客户端状态读取失败，请查看运行日志。"):"客户端模组等待服务启动并更新状态。";UpdateModuleFeedback(m);}else {FeatureStatus.Text="客户端模组将在游戏启动后加载。";UpdateModuleFeedback(null);}}catch(Exception ex){if(showError)throw;StatusText.Text=UiText.Summary(ex.Message);}}
 void UpdateModuleFeedback(JsonNode? state){
  var timestamp=state?["at"]?.GetValue<long>()??0;bool fresh=Math.Abs(DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()-timestamp)<10000;
  foreach(var mod in repo.Config.Mods){if(mod.Manifest.Adapter=="external"){mod.UpdateRuntime(backend.ExternalModFeedback(mod) is string feedback?UiText.Summary(feedback):null);continue;}var key=mod.Manifest.Adapter switch{"player-effects"=>"effects","vision"=>"vision","death-fast"=>"death",_=>""};var module=fresh&&key!=""?state?["modules"]?[key]:null;mod.UpdateRuntime(module==null?null:UiText.Summary(mod.Manifest.Adapter=="player-effects"?EffectFeedbackLogic.Describe(mod,module):module["message"]?.ToString()));}
 }
 void OpenFolder_Click(object sender,RoutedEventArgs e)=>Process.Start(new ProcessStartInfo("explorer.exe",repo.Root){UseShellExecute=true});
 async void Admin_Click(object sender,RoutedEventArgs e){if(busy)return;await Work("切换管理员运行",async()=>{SavePaths();await backend.Shutdown();try{Process.Start(new ProcessStartInfo(Environment.ProcessPath!){UseShellExecute=true,Verb="runas",WorkingDirectory=repo.Root,Arguments="--wait-for-exit "+Environment.ProcessId});allowClose=true;_ = Dispatcher.BeginInvoke(new Action(Close));}catch(Win32Exception){StatusText.Text="已取消管理员运行。";}});}
 void Preferences_Click(object sender,RoutedEventArgs e){var w=new Window{Owner=this,Title="程序设置",Width=540,Height=420,ResizeMode=ResizeMode.NoResize,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=Background};var p=new StackPanel{Margin=new Thickness(28)};w.Content=p;p.Children.Add(new TextBlock{Text="脚本运行引擎",FontSize=21,FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,0,0,20)});var engine=new ComboBox{ItemsSource=new[]{"PowerShell 5.1（默认）","PowerShell 7"},SelectedIndex=repo.Config.PowerShell=="7"?1:0};p.Children.Add(engine);p.Children.Add(new TextBlock{Text="PowerShell 7 · pwsh.exe 路径",Foreground=Bf4Theme.Muted,Margin=new Thickness(0,18,0,8)});var box=new TextBox{Text=repo.Config.PowerShell7Path};p.Children.Add(box);var pick=new Button{Content="选择 pwsh.exe",Margin=new Thickness(0,9,0,12),HorizontalAlignment=HorizontalAlignment.Left};pick.Click+=(s,a)=>{var d=new Microsoft.Win32.OpenFileDialog{Filter="PowerShell|pwsh.exe"};if(d.ShowDialog(w)==true)box.Text=d.FileName;};p.Children.Add(pick);p.Children.Add(new TextBlock{Text="切换引擎后，新任务使用所选版本。\n关闭主窗口时保存进度并停止本目录的服务。",FontSize=12,Foreground=Bf4Theme.Muted,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,16)});var save=new Button{Content="保存",Style=(Style)FindResource("Primary"),HorizontalAlignment=HorizontalAlignment.Right};save.Click+=(s,a)=>{if(engine.SelectedIndex==1&&!File.Exists(box.Text)){MessageBox.Show(w,"请选择 pwsh.exe。");return;}repo.Config.PowerShell=engine.SelectedIndex==1?"7":"5.1";repo.Config.PowerShell7Path=box.Text;repo.Save();RefreshLabels();w.Close();ShowNotice("程序设置已保存","新任务将使用 PowerShell "+repo.Config.PowerShell+"。");};p.Children.Add(save);w.ShowDialog();}
 void LoadRotationEditor(){loadingRotation=true;rotationRows.Clear();foreach(var row in repo.Config.Rotation??new()){var copy=row.Clone();ObserveRotation(copy);rotationRows.Add(copy);}loadingRotation=false;RotationCount.Text=rotationRows.Count+" 项";RotationHint.Text="轮换已读取。保存后在下次开服或重启游戏服时应用。";}
 void ObserveRotation(RotationEntry row){row.AllMaps=repo.Maps;row.PropertyChanged+=(s,e)=>MarkRotationChanged();}
 void FilterRotationMaps(){var selected=AddMapCombo.SelectedValue as string;var mode=AddModeCombo.SelectedValue as string;var choices=repo.Maps.Where(m=>m.Modes.Count==0||m.Modes.Contains(mode??"ConquestLarge0")).ToList();AddMapCombo.ItemsSource=choices;AddMapCombo.SelectedValue=choices.Any(m=>m.Id==selected)?selected:choices.FirstOrDefault()?.Id;}
 void MarkRotationChanged(){if(loadingRotation)return;RotationCount.Text=rotationRows.Count+" 项";RotationHint.Text="轮换有修改，点击保存。";}
 List<RotationEntry> ReadRotationEditor(){if(!RotationGrid.CommitEdit(DataGridEditingUnit.Cell,true)||!RotationGrid.CommitEdit(DataGridEditingUnit.Row,true))throw new Exception("回合数请填写 1～10 的整数。");var rows=rotationRows.Select(r=>r.Clone()).ToList();repo.ValidateRotation(rows);return rows;}
 void AddRotation_Click(object sender,RoutedEventArgs e){try{if(rotationRows.Count>=32)throw new Exception("地图轮换最多 32 项。");if(AddMapCombo.SelectedValue is not string map||AddModeCombo.SelectedValue is not string mode)throw new Exception("先选择地图和模式。");if(!int.TryParse(AddRoundsBox.Text,NumberStyles.Integer,CultureInfo.InvariantCulture,out int rounds)||rounds<1||rounds>10)throw new Exception("每项地图的回合数为 1～10。");repo.ValidateRotation(new[]{new RotationEntry{Map=map,Mode=mode,Rounds=rounds}});var row=new RotationEntry{Map=map,Mode=mode,Rounds=rounds};ObserveRotation(row);rotationRows.Add(row);RotationGrid.SelectedItem=row;MarkRotationChanged();}catch(Exception ex){ShowNotice("地图没有添加",ex.Message,true);}}
 void Rotation_LoadingRow(object sender,DataGridRowEventArgs e)=>e.Row.Header=(e.Row.GetIndex()+1).ToString();
 RotationEntry? RotationItem(object sender)=>(sender as FrameworkElement)?.DataContext as RotationEntry;
 void RefreshRotationHeaders(){_ = Dispatcher.BeginInvoke(new Action(()=>{for(int i=0;i<RotationGrid.Items.Count;i++)if(RotationGrid.ItemContainerGenerator.ContainerFromIndex(i) is DataGridRow row)row.Header=(i+1).ToString();}),DispatcherPriority.Loaded);}
 void MoveRotation(RotationEntry row,int target){if(target<0||target>=rotationRows.Count)return;if(!RotationGrid.CommitEdit(DataGridEditingUnit.Cell,true)||!RotationGrid.CommitEdit(DataGridEditingUnit.Row,true))return;var index=rotationRows.IndexOf(row);if(index<0||index==target)return;rotationRows.Move(index,target);RefreshRotationHeaders();RotationGrid.SelectedItem=row;MarkRotationChanged();}
 void RotationUp_Click(object sender,RoutedEventArgs e){if(RotationItem(sender) is {} row)MoveRotation(row,rotationRows.IndexOf(row)-1);}
 void RotationDown_Click(object sender,RoutedEventArgs e){if(RotationItem(sender) is {} row)MoveRotation(row,rotationRows.IndexOf(row)+1);}
 void RotationRemove_Click(object sender,RoutedEventArgs e){if(RotationItem(sender) is {} row){if(!RotationGrid.CommitEdit(DataGridEditingUnit.Cell,true)||!RotationGrid.CommitEdit(DataGridEditingUnit.Row,true))return;rotationRows.Remove(row);RefreshRotationHeaders();MarkRotationChanged();}}
 void Rotation_MouseDown(object sender,MouseButtonEventArgs e){rotationDrag=null;rotationDragStart=e.GetPosition(RotationGrid);if(FindParent<System.Windows.Controls.Primitives.DataGridRowHeader>(e.OriginalSource as DependencyObject)!=null)rotationDrag=FindParent<DataGridRow>(e.OriginalSource as DependencyObject)?.Item as RotationEntry;}
 void Rotation_MouseMove(object sender,MouseEventArgs e){if(rotationDrag!=null&&e.LeftButton==MouseButtonState.Pressed&&(e.GetPosition(RotationGrid)-rotationDragStart).Length>7){var row=rotationDrag;rotationDrag=null;DragDrop.DoDragDrop(RotationGrid,new DataObject("BF4Rotation",row),DragDropEffects.Move);}}
 void Rotation_DragOver(object sender,DragEventArgs e){e.Effects=e.Data.GetDataPresent("BF4Rotation")?DragDropEffects.Move:DragDropEffects.None;e.Handled=true;}
 void Rotation_Drop(object sender,DragEventArgs e){e.Handled=true;if(e.Data.GetData("BF4Rotation") is RotationEntry row){var target=FindParent<DataGridRow>(e.OriginalSource as DependencyObject)?.Item as RotationEntry;MoveRotation(row,target==null?rotationRows.Count-1:rotationRows.IndexOf(target));}}
 async void SaveRotation_Click(object sender,RoutedEventArgs e)=>await Work("保存地图轮换",async()=>{var rows=ReadRotationEditor();await backend.SaveRotation(rows);RotationHint.Text="轮换已保存，不会切换当前对局；下次开服或重启游戏服时应用。";Log("地图轮换已保存，共 "+rows.Count+" 项。");SetCompletion("地图轮换已保存","不会跳转当前对局；下次开服或重启游戏服时应用。");});
 async void SaveRotationRestart_Click(object sender,RoutedEventArgs e)=>await Work("保存轮换并重启游戏服",async()=>{await backend.SaveRotation(ReadRotationEditor());await backend.Control("RestartGame");RotationHint.Text="轮换已应用到重启后的游戏服。";await RefreshState(false);},OperationKind.RestartServer);
 void ReloadRotation_Click(object sender,RoutedEventArgs e){LoadRotationEditor();StatusText.Text="已重新读取保存的轮换。";ShowNotice("地图轮换已重新读取","未保存的编辑已还原。");}
 void BuildFields(){ServerFields.Children.Clear();fieldEditors.Clear();foreach(var g in repo.Fields.Where(f=>!f.Hidden).GroupBy(f=>f.Group)){var box=new Border{Style=(Style)FindResource("Card")};var p=new StackPanel();box.Child=p;p.Children.Add(new TextBlock{Text=g.Key,FontSize=16,FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,0,0,20)});var grid=new Grid();grid.ColumnDefinitions.Add(new ColumnDefinition());grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(26)});grid.ColumnDefinitions.Add(new ColumnDefinition());int n=0;foreach(var f in g){if(n%2==0)grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});var ed=new FieldEditor(f,repo.Config.Server.GetValueOrDefault(f.Id));var view=ed.View();Grid.SetColumn(view,n%2==0?0:2);Grid.SetRow(view,n/2);grid.Children.Add(view);fieldEditors.Add(ed);if(f.Id=="serverPreset"&&ed.Control is ComboBox presetCombo)presetCombo.SelectionChanged+=(sender,args)=>{if(ready)RefreshLabels();};n++;}p.Children.Add(grid);ServerFields.Children.Add(box);}}
 void RefreshPresetEditors(string? effective=null){
  var selected=effective??fieldEditors.FirstOrDefault(ed=>ed.Field.Id=="serverPreset")?.Read()?.ToString()??"CUSTOM";
  foreach(var editor in fieldEditors){bool controlled=selected!="CUSTOM"&&ServerPresetLogic.ControlledFields.Contains(editor.Field.Id);editor.Control.IsEnabled=!editor.Field.Locked&&!controlled;if(controlled){editor.OverrideHint.Text="由"+ServerPresetLogic.Label(selected)+"预设控制；此处保留自定义值。";editor.OverrideHint.Visibility=Visibility.Visible;}}
 }
 void SaveServer(){var next=fieldEditors.ToDictionary(x=>x.Field.Id,x=>x.Read());foreach(var f in repo.Fields.Where(f=>f.Hidden))next[f.Id]=repo.Config.Server.GetValueOrDefault(f.Id)?.DeepClone();Repository.Validate(next,repo.Fields);repo.Config.Server=next;repo.Plan();repo.Save();ServerHint.Text="已保存，服务端下次启动时应用。";RefreshLabels();}
 void SaveServer_Click(object sender,RoutedEventArgs e){try{SaveServer();StatusText.Text="服务端基础设置已保存。";ShowNotice("服务端设置已保存","下次开服或重启游戏服时应用。");}catch(Exception ex){ShowNotice("设置未保存",ex.Message,true);}}
 async void SaveRestart_Click(object sender,RoutedEventArgs e)=>await Work("保存并重启游戏服",async()=>{SaveServer();await backend.Control("RestartGame");await RefreshState(false);},OperationKind.RestartServer);
 void RefreshMods_Click(object sender,RoutedEventArgs e){try{int added=repo.RefreshModDirectory();RefreshModCards();RefreshLabels();backend.EnsureExternalMods();var errors=repo.ModDirectoryMessages.Count;ShowNotice("模组目录已刷新",$"新增 {added} 个版本。"+(errors>0?$"有 {errors} 个目录需要检查，详情见运行记录。":""),false,errors>0);foreach(var message in repo.ModDirectoryMessages)Log(message);}catch(Exception ex){ShowNotice("模组目录未刷新",ex.Message,true);}}
 void Import_Click(object sender,RoutedEventArgs e){var dialog=new Microsoft.Win32.OpenFileDialog{Filter="BF4 模组包|*.zip;*.bf4mod",Multiselect=true};if(dialog.ShowDialog(this)==true)ImportFiles(dialog.FileNames);}
 void ImportFiles(IEnumerable<string> files){int added=0,existing=0,failed=0;string firstError="";foreach(var file in files){try{int before=repo.Config.Mods.Count;var item=repo.Import(file);if(repo.Config.Mods.Count>before){added++;Log("已添加："+item.Name+" "+item.Version);}else existing++;}catch(Exception ex){failed++;firstError=firstError==""?ex.Message:firstError;Log(Path.GetFileName(file)+"："+ex.Message);}}RefreshModCards();RefreshLabels();if(failed>0)ShowNotice(added>0?"部分模组已添加":"模组未添加",$"新增 {added} 项，已有 {existing} 项，未添加 {failed} 项。"+firstError,added==0,true);else ShowNotice(added>0?"模组已添加":"这些版本已经在列表中",$"新增 {added} 项，已有 {existing} 项。新模组默认关闭；已有模组保留当前版本。",false,added==0);}
 ModItem? Item(object sender)=>(sender as FrameworkElement)?.DataContext as ModItem;
 static T? FindParent<T>(DependencyObject? child) where T:DependencyObject {while(child!=null){if(child is T t)return t;child=child is System.Windows.Media.Visual||child is System.Windows.Media.Media3D.Visual3D?VisualTreeHelper.GetParent(child):LogicalTreeHelper.GetParent(child);}return null;}
 void Plan_Click(object sender,RoutedEventArgs e){try{var p=repo.Plan();var body=string.Join(Environment.NewLine,p.Owners.Select(x=>(repo.Fields.FirstOrDefault(f=>f.Id==x.Key)?.Label??x.Key)+" = "+p.Values[x.Key]+"\n    来源："+x.Value));if(body=="")body="当前没有启用配置覆盖模组，使用服务端基础设置。";var preset=p.Values.GetValueOrDefault("serverPreset")?.ToString()??"CUSTOM";body="已保存的服务端规则预设："+ServerPresetLogic.Label(preset)+"（"+preset+"）\n"+(preset=="CUSTOM"?"使用下方自定义配置与模组覆盖。":"普通／硬核预设在开服时统一应用；下方为预设应用前的模组覆盖，被预设控制的参数以游戏预设为准。")+"\n\n"+body;var w=new Window{Owner=this,Title="最终配置与覆盖来源",Width=640,Height=550,WindowStartupLocation=WindowStartupLocation.CenterOwner};w.Content=new TextBox{Text=body,IsReadOnly=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Margin=new Thickness(20)};w.ShowDialog();}catch(Exception ex){MessageBox.Show(this,ex.Message,"加载顺序");}}
 async void Window_Closing(object? sender,CancelEventArgs e){if(allowClose)return;e.Cancel=true;if(closing)return;if(busy){closeRequested=true;StatusText.Text="当前操作完成后保存并关闭。";OperationDetail.Text+=" · 完成后将保存进度并关闭";return;}closing=true;timer.Stop();await Dispatcher.Yield(DispatcherPriority.Background);await Work("保存进度并停止服务",async()=>{repo.Save();await backend.Shutdown();allowClose=true;},OperationKind.StopServer);if(allowClose)_ = Dispatcher.BeginInvoke(new Action(Close));else{closing=false;timer.Start();}}
}




